src={s['id']:s for pg in d['pages'] for s in pg['paragraphs']}
assert [pg['printed_page'] for pg in d['pages']]==list(range(519,529))
assert len(src)==sum(len(pg['paragraphs']) for pg in d['pages'])
assert set(src)=={sid for u in d['units'] for sid in u['source_ids']}
for s in src.values():assert s['sha256']==hashlib.sha256(s['ar'].encode()).hexdigest()
for u in d['units']:
 assert u['ar']==' '.join(src[sid]['ar'] for sid in u['source_ids'])
 assert re.findall(r'\{[^{}]+\}',u['ar'])==re.findall(r'\{[^{}]+\}',u['ru'])
 if u['id']=='v4-p528-04-ru':
  assert u['ar'].split('{')[-1]==u['ru'].split('{')[-1]
  assert u['ar'].count('{')==u['ar'].count('}')+1
 else:assert u['ar'].count('{')==u['ar'].count('}')
 u['draft_status']='self_reviewed'
d['completed']=True
json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
